const stories=[{id:`st_${placeId}_fra_motstandserfaring_til_museum`,quality_profile:"episode_v1",type:"historical_event",title:"Fra motstandserfaring til museum",year:1962,place_id:placeId,summary:"En komité fikk oppgaven med å gjøre ulike motstandserfaringer, gjenstander og arkiver til en offentlig museumsfortelling.",story:"I juni 1962 møttes representanter for norsk motstandsbevegelse og besluttet å arbeide for et hjemmefrontmuseum. De oppnevnte en komité som skulle samle dokumentasjon og forme en institusjon.\n\nFra september 1963 fikk komiteen lønnsmidler gjennom Forsvarsdepartementet. Våren 1966 ble museet egen stiftelse. Samtidig måtte eldre rom i Bindingsverkshuset og Det dobbelte batteri restaureres og tilpasses samling, arkiv og publikum.\n\nDaværende kronprins Harald åpnet museet 7. mai 1970. Åpningen gjorde motstandsdeltakernes prosjekt offentlig, men den gjorde ikke én utstilling til en fullstendig fortelling om alle erfaringer under okkupasjonen. Museets historie viser derfor både bevaring og utvalg: kilder reddes, ordnes og vises, mens andre perspektiver må hentes fram gjennom videre forskning.",episode:{actors:["representanter for motstandsbevegelsen","museumskomiteen","Forsvarsdepartementet","daværende kronprins Harald"],date:"1962–1970",action:"Komiteen sikret organisasjon, midler, lokaler og en kronologisk utstilling.",consequence:"Norges Hjemmefrontmuseum åpnet som offentlig museum 7. mai 1970."},sources:[{title:"Sikt – Norges Hjemmefrontmuseum",url:urls.sikt},{title:"Kongehuset – Besøkte krigsveteraner",url:urls.royalOpening},{title:"SNL – Norges Hjemmefrontmuseum",url:urls.snl}],tags:["museumshistorie","motstand","stiftelse","historiebruk"],related_people:[personId],related_places:[],next_scenes:[{place_id:"akershus_festning",reason:"Se museumsbygningen som ett av flere tydelig avgrensede steder på festningen."},{place_id:"mollergata_19",reason:"Følg okkupasjonshistorien til et konkret fengselssted med egne kilder."}],score:{narrative:3,historical:3,source:5,play_value:3,originality:3,total:17},arc:{start:"Motstandsdeltakere beslutter å opprette et museum.",middle:"Komiteen bygger organisasjon og tilpasser eldre festningsrom.",end:"Museet åpner, og en kuratert etterkrigsfortelling blir offentlig."}}];
